int main(int argc,char** argv){if(argc<4)return 2;auto args=Value(ValueMap{{"root",std::string(argv[1])},{"seed",std::stoi(argv[2])},{"rotation",argc>4?std::stoi(argv[4]):0},{"simultaneous",argc>5?std::stoi(argv[5]):0},{"systems",argc>6?std::stoi(argv[6]):16}});std::cout<<se4_audit("initialize",script::toJson(args)->c_str())<<std::endl;const int turns=std::stoi(argv[3]);for(int t=0;t<turns;t+=10){auto next=se4_audit("step","{\"turns\":10}");std::cout<<next<<std::endl;auto value=script::parseJson(next);if(!value||value->find("error"))return 1;if(value->find("gameOver")->asBool())break;std::cerr<<"seed "<<argv[2]<<" turn "<<value->find("turn")->asInt()<<std::endl;}return 0;}
